SELECT agents.hourly_cost_usd
FROM support.agents
WHERE agents.display_name = 'Farhana Khan' AND agents.team = 'sales' AND agents.is_active = true;

SELECT SUM(total_cost_usd) AS total_cost
FROM marts.fct_outcomes
WHERE split = 'test' AND arm = 'primary' AND tenant_id NOT LIKE 'test-%';

SELECT AVG(input_tokens + output_tokens) AS avg_total_tokens
FROM marts.fct_requests
WHERE split = 'test' AND provider = 'vllm';

SELECT COUNT(*) AS number_of_tenants
FROM marts.dim_tenant
WHERE tenant_id NOT LIKE 'test-%';

SELECT monthly_budget_usd
FROM marts.dim_tenant
WHERE tenant_id = 'billing';

SELECT COUNT(*) AS cache_hit_count
FROM marts.fct_requests
WHERE cache_status = 'HIT';

SELECT COUNT(*) 
FROM support.tickets 
WHERE tenant_id = 'support' AND priority = 'high';

SELECT COUNT(*) 
FROM support.agents 
WHERE team = 'billing';

SELECT COUNT(DISTINCT gold_label) AS distinct_gold_intents
FROM marts.fct_outcomes
WHERE split = 'test';

SELECT COUNT(*) 
FROM support.tickets 
WHERE tenant_id = 'support' AND status = 'open';

SELECT COUNT(*) 
FROM marts.fct_requests 
WHERE http_status != 200;

SELECT COUNT(*) 
FROM support.agents 
WHERE hourly_cost_usd > 6;

SELECT COUNT(*) AS resolved_tickets
FROM support.tickets
WHERE status IN ('resolved', 'closed');

SELECT COUNT(*) AS current_headcount
FROM support.agents
WHERE is_active = true AND team NOT LIKE 'test-%';

SELECT SUM(total_cost_usd) AS total_spent
FROM marts.fct_outcomes
WHERE split = 'test' AND arm = 'primary' AND setup = 'B_local';

SELECT COUNT(DISTINCT ticket_id) AS reopened_tickets
FROM support.ticket_events
WHERE event_type = 'reopened';

SELECT AVG(hourly_cost_usd) AS avg_hourly_cost_usd
FROM support.agents
WHERE is_active AND team NOT LIKE 'test-%';
